const { chromium } = require('/home/user/Web-Calculator-fresh/sabee-khan-calculator/node_modules/playwright');
const OUT = '/tmp/claude-0/-home-user/aea11bb9-83e3-5459-94fc-a24723a2132a/scratchpad/s2rev';
const URL = 'http://localhost:4174/';
const states = {
  idle: null,
  pass: ['17.5', '23', null],
  fail: ['15.5', '23', null],
  twoerr: ['abc', '-5', null],
  passempty: ['17.5', '23', ''],
};
(async () => {
  const browser = await chromium.launch();
  const report = [];
  for (const scheme of ['light', 'dark']) {
    for (const w of [320, 375, 768, 1280]) {
      const ctx = await browser.newContext({ viewport: { width: w, height: 900 }, colorScheme: scheme });
      const page = await ctx.newPage();
      const errs = [];
      page.on('console', (m) => { if (m.type() !== 'log') errs.push(m.text()); });
      for (const [name, vals] of Object.entries(states)) {
        await page.goto(URL);
        const inputs = page.locator('input');
        if (vals) {
          for (let i = 0; i < 3; i++) if (vals[i] !== null) await inputs.nth(i).fill(vals[i]);
          await inputs.nth(0).focus();
          await page.keyboard.press('Enter');
          await inputs.nth(2).blur();
          await page.mouse.click(1, 1);
        }
        await page.waitForTimeout(250);
        const m = await page.evaluate(() => {
          const r = (s) => { const e = document.querySelector(s); return e ? e.getBoundingClientRect() : null; };
          const rb = r('.result-body'); const card = r('.card');
          const kids = [...document.querySelector('.result-body').children];
          const contentH = kids.reduce((a, k) => Math.max(a, k.getBoundingClientRect().bottom), rb.top) - rb.top;
          return {
            scrollW: document.documentElement.scrollWidth, cardBottom: card.bottom, cardH: card.height,
            rbH: rb.height, contentH: Math.round(contentH), resultText: document.querySelector('.result-body').innerText.replace(/\n/g, ' | '),
            title: document.title, passVal: document.querySelectorAll('input')[2].value,
          };
        });
        report.push({ scheme, w, name, ...m, errs: errs.length });
        await page.screenshot({ path: `${OUT}/${name}-${w}-${scheme}.png`, fullPage: true });
      }
      await ctx.close();
    }
  }
  console.log(JSON.stringify(report, null, 0).replace(/},{/g, '},\n{'));
  await browser.close();
})();

