const H = { 375: 812, 768: 1024, 1280: 800 };
async function fill(page, vals) {
  await page.goto('http://localhost:4174/');
  const inputs = page.locator('input');
  for (let i = 0; i < 3; i++) await inputs.nth(i).fill(vals[i]);
  await page.locator('body').click({ position: { x: 2, y: 2 } });
  await page.evaluate(() => document.activeElement && document.activeElement.blur());
  await page.waitForTimeout(700);
}
(async () => {
  const browser = await chromium.launch();
  for (const w of [375, 768, 1280]) for (const scheme of ['light', 'dark']) {
    const ctx = await browser.newContext({ viewport: { width: w, height: H[w] }, colorScheme: scheme });
    const page = await ctx.newPage();
    await fill(page, ['17.5', '23', '70']);
    const t = await page.locator('.result-body').innerText();
    console.log(w, scheme, JSON.stringify(t));
    await page.screenshot({ path: `${SHOTS}/final-${w}-${scheme}.png` });
    if (w === 375 && scheme === 'light') {
      await fill(page, ['abc', '-5', '70']);
      console.log('error', JSON.stringify(await page.locator('.card').innerText()));
      await page.screenshot({ path: `${SHOTS}/final-error-375-light.png` });
    }
    await ctx.close();
  }
  // mockup self-check
  for (const w of [375, 1280]) {
    const ctx = await browser.newContext({ viewport: { width: w, height: 900 } });
    const page = await ctx.newPage();
    const errs = []; page.on('console', (m) => errs.push(m.text())); page.on('pageerror', (e) => errs.push(String(e)));
    await page.goto('file://' + DIR + '/mockup.html');
    const m = await page.evaluate(() => ({ sw: document.documentElement.scrollWidth, btn: document.querySelectorAll('button,kbd,.actions').length, scripts: document.scripts.length }));
    console.log('mockup', w, JSON.stringify(m), errs.length);
    await page.screenshot({ path: `${SCR}/mockup-${w}.png`, fullPage: true });
    await ctx.close();
  }
  await browser.close();
})();

